/*!
 * Themeasy — Before / After
 *
 * Interactive controller for the Before/After image comparison widget. The
 * comparison itself is pure CSS (clip-path driven by --tms-before-after-position);
 * this script only layers the draggable / hover / keyboard interaction on top, so
 * the widget stays fully visible with no JS. Short-circuits on the editor --static
 * class, is safe to re-init (per-element bound flag + reset), and auto-inits on
 * DOM ready.
 *
 * - Single namespace: window.Themeasy.beforeAfter
 * - Pointer Events (unified mouse + touch + pen)
 * - Three skins: handle (drag) / reveal (drag without handle) / hover (follow pointer)
 * - Keyboard: arrow keys (1%), Shift+arrow (10%), Home/End (0/100), PageUp/PageDown (10%)
 * - ARIA slider: aria-valuenow synced on every update
 * - Reduced-motion aware (hover skin snaps instead of easing)
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window, document) {
  'use strict'

  // ------------------------------------------------------------------------
  // Namespace
  // ------------------------------------------------------------------------
  window.Themeasy = window.Themeasy || {}
  window.Themeasy.beforeAfter = window.Themeasy.beforeAfter || {}

  // ------------------------------------------------------------------------
  // Selectors & constants
  // ------------------------------------------------------------------------
  const SELECTOR_ROOT = '.tms-before-after'
  const SELECTOR_SLIDER = '.tms-before-after__slider'
  const CLASS_STATIC = 'tms-before-after--static'
  const CLASS_DRAGGING = 'tms-before-after--dragging'
  const CSS_VAR_POSITION = '--tms-before-after-position'
  const BOUND_FLAG = 'tmsBeforeAfterBound'

  // ------------------------------------------------------------------------
  // Utils
  // ------------------------------------------------------------------------
  function onDomReady(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn, { once: true })
      return
    }
    fn()
  }

  function clamp(value, min, max) {
    return Math.max(min, Math.min(max, value))
  }

  function prefersReducedMotion() {
    return window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches
  }

  // ------------------------------------------------------------------------
  // Instance binding
  // ------------------------------------------------------------------------

  /**
   * Bind a single Before/After instance.
   *
   * @param {HTMLElement} el Wrapper element.
   */
  function bindInstance(el) {
    const slider = el.querySelector(SELECTOR_SLIDER)
    if (!slider) return

    const skin = el.getAttribute('data-skin') || 'handle'
    const orientation = el.getAttribute('data-orientation') || 'horizontal'
    const startAttr = parseFloat(el.getAttribute('data-start'))
    const startValue = isNaN(startAttr) ? 50 : clamp(startAttr, 0, 100)

    let position = startValue
    let dragging = false
    let pointerId = null

    setPosition(position)

    /**
     * Apply a position value and sync ARIA + CSS variable.
     *
     * @param {number} value Position in 0..100.
     */
    function setPosition(value) {
      position = clamp(value, 0, 100)
      el.style.setProperty(CSS_VAR_POSITION, position + '%')
      slider.setAttribute('aria-valuenow', String(Math.round(position)))
    }

    /**
     * Convert a pointer event to a position percentage inside the frame.
     *
     * @param {PointerEvent} event Pointer event.
     * @returns {number} 0..100.
     */
    function eventToPosition(event) {
      const rect = el.getBoundingClientRect()
      if (orientation === 'vertical') {
        if (rect.height === 0) return 50
        return ((event.clientY - rect.top) / rect.height) * 100
      }
      if (rect.width === 0) return 50
      return ((event.clientX - rect.left) / rect.width) * 100
    }

    /**
     * Start a drag or capture a single move depending on skin.
     *
     * @param {PointerEvent} event Pointer event.
     */
    function onPointerDown(event) {
      // Allow native scrolling on touch start when skin is hover (no drag).
      if (skin === 'hover') return

      // Only primary button / primary contact.
      if (event.button !== undefined && event.button !== 0) return

      dragging = true
      pointerId = event.pointerId
      el.classList.add(CLASS_DRAGGING)

      try {
        slider.setPointerCapture(event.pointerId)
      } catch (e) {
        // Ignore — some browsers may refuse capture on non-primary pointers.
      }

      setPosition(eventToPosition(event))
      event.preventDefault()
    }

    /**
     * Continue drag or follow pointer (hover skin).
     *
     * @param {PointerEvent} event Pointer event.
     */
    function onPointerMove(event) {
      if (skin === 'hover') {
        // Only follow when a primary pointer is hovering (no drag required).
        if (event.pointerType === 'touch') return
        setPosition(eventToPosition(event))
        return
      }

      if (!dragging) return
      if (pointerId !== null && event.pointerId !== pointerId) return

      setPosition(eventToPosition(event))
      event.preventDefault()
    }

    /**
     * End drag.
     *
     * @param {PointerEvent} event Pointer event.
     */
    function onPointerUp(event) {
      if (!dragging) return
      if (pointerId !== null && event.pointerId !== pointerId) return

      dragging = false
      pointerId = null
      el.classList.remove(CLASS_DRAGGING)

      try {
        slider.releasePointerCapture(event.pointerId)
      } catch (e) {
        // Ignore.
      }
    }

    /**
     * Reset to start position when pointer leaves (hover skin only).
     */
    function onPointerLeave() {
      if (skin !== 'hover') return
      if (prefersReducedMotion()) return
      setPosition(startValue)
    }

    /**
     * Keyboard navigation on the slider role.
     *
     * @param {KeyboardEvent} event Keyboard event.
     */
    function onKeyDown(event) {
      const key = event.key
      const step = event.shiftKey ? 10 : 1
      const isHorizontal = orientation === 'horizontal'

      let delta = 0
      let jumpTo = null

      if (isHorizontal) {
        if (key === 'ArrowLeft') delta = -step
        else if (key === 'ArrowRight') delta = step
      } else {
        if (key === 'ArrowUp') delta = -step
        else if (key === 'ArrowDown') delta = step
      }

      if (key === 'PageDown') delta = -10
      else if (key === 'PageUp') delta = 10
      else if (key === 'Home') jumpTo = 0
      else if (key === 'End') jumpTo = 100

      if (delta === 0 && jumpTo === null) return

      event.preventDefault()

      if (jumpTo !== null) {
        setPosition(jumpTo)
      } else {
        setPosition(position + delta)
      }
    }

    /**
     * Prevent native image drag from stealing the pointer sequence.
     *
     * @param {DragEvent} event Drag event.
     */
    function onImageDragStart(event) {
      event.preventDefault()
    }

    // ------------------------------------------------------------------------
    // Bind listeners. Keep references on the element so reset() can remove them.
    // ------------------------------------------------------------------------
    const teardown = []

    slider.addEventListener('pointerdown', onPointerDown)
    slider.addEventListener('pointermove', onPointerMove)
    slider.addEventListener('pointerup', onPointerUp)
    slider.addEventListener('pointercancel', onPointerUp)
    slider.addEventListener('pointerleave', onPointerLeave)
    slider.addEventListener('keydown', onKeyDown)

    teardown.push(function () {
      slider.removeEventListener('pointerdown', onPointerDown)
      slider.removeEventListener('pointermove', onPointerMove)
      slider.removeEventListener('pointerup', onPointerUp)
      slider.removeEventListener('pointercancel', onPointerUp)
      slider.removeEventListener('pointerleave', onPointerLeave)
      slider.removeEventListener('keydown', onKeyDown)
    })

    el.querySelectorAll('.tms-before-after__img').forEach(function (img) {
      img.addEventListener('dragstart', onImageDragStart)
      teardown.push(function () {
        img.removeEventListener('dragstart', onImageDragStart)
      })
    })

    el._tmsBeforeAfterTeardown = teardown
  }

  /**
   * Tear down a single instance (remove listeners + bound flag).
   *
   * @param {HTMLElement} el Wrapper element.
   */
  function unbindInstance(el) {
    if (Array.isArray(el._tmsBeforeAfterTeardown)) {
      el._tmsBeforeAfterTeardown.forEach(function (off) {
        off()
      })
      el._tmsBeforeAfterTeardown = null
    }
    el.classList.remove(CLASS_DRAGGING)
    delete el.dataset[BOUND_FLAG]
  }

  // ------------------------------------------------------------------------
  // Public API
  // ------------------------------------------------------------------------

  /**
   * Reset Before/After instances inside the given root (or whole document).
   *
   * @param {ParentNode} [root] Root node to scan. Defaults to document.
   */
  window.Themeasy.beforeAfter.reset = function (root) {
    const scope = root || document
    scope.querySelectorAll(SELECTOR_ROOT).forEach(unbindInstance)
  }

  /**
   * Initialize Before/After instances inside the given root (or whole document).
   *
   * @param {ParentNode} [root] Root node to scan. Defaults to document.
   */
  window.Themeasy.beforeAfter.init = function (root) {
    const scope = root || document
    const roots = scope.querySelectorAll(SELECTOR_ROOT)
    if (!roots.length) return

    roots.forEach(function (el) {
      // Editor preview is static until the preview runtime drops the class.
      if (el.classList.contains(CLASS_STATIC)) return
      if (el.dataset[BOUND_FLAG] === '1') return
      bindInstance(el)
      el.dataset[BOUND_FLAG] = '1'
    })
  }

  // ------------------------------------------------------------------------
  // Central boot
  // ------------------------------------------------------------------------
  function boot() {
    if (document.querySelector(SELECTOR_ROOT)) {
      window.Themeasy.beforeAfter.init()
    }
  }

  window.Themeasy.beforeAfter.boot = boot

  onDomReady(boot)
})(window, document)
